"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["41101"],{70896(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.referencia_temporal_fatos.fase_nao_pertence_ao_processo","status":422,"titulo":"A fase de refer\xeancia n\xe3o pertence ao cronograma deste processo"},"descricao":{"codigo":"uniplus.selecao.referencia_temporal_fatos.fase_nao_pertence_ao_processo","requisitos":[],"oQueAconteceu":["Os tipos `INICIO_FASE` e `FIM_FASE` da refer\xeancia temporal dos fatos contam a idade do candidato a\\npartir do in\xedcio ou do fim de uma fase, e a fase informada n\xe3o est\xe1 no cronograma deste processo. A\\nmensagem traz o identificador da fase recusada. Nada foi alterado.","A refer\xeancia temporal dos fatos \xe9 a pol\xedtica, no n\xedvel do processo, que define a refer\xeancia para apurar a faixa\\net\xe1ria do candidato: de onde vem a data em que a idade \xe9 contada. Uma \xfanica pol\xedtica vale para todas\\nas regras do processo que citam a idade. Ela \xe9 dada por um tipo (`FIM_INSCRICAO`, `INICIO_FASE`,\\n`FIM_FASE` ou `DATA_ESPECIFICA`) e, conforme o tipo, por uma data ou por uma fase do cronograma. Para\\nremover a refer\xeancia, o pedido omite o tipo, a data e a fase; o tipo omitido com data ou fase presentes\\n\xe9 recusado antes, na valida\xe7\xe3o do pedido, e n\xe3o chega \xe0s confer\xeancias desta p\xe1gina.","A confer\xeancia vem depois das de forma do tipo, da data e da fase\\n([`fase_incoerente_com_tipo`](/erros/uniplus.selecao.referencia_temporal_fatos.fase_incoerente_com_tipo)),\\ne depois da verifica\xe7\xe3o de que a edi\xe7\xe3o est\xe1 liberada (processo em rascunho). Ela vale s\xf3 para esses dois tipos; `FIM_INSCRICAO` e `DATA_ESPECIFICA` n\xe3o\\nusam fase. Quando a fase estava no cronograma na defini\xe7\xe3o e saiu dele depois, a recusa \xe9 outra, na\\npublica\xe7\xe3o\\n([`referencia_temporal_fatos_fase_inexistente`](/erros/uniplus.selecao.processo_seletivo.referencia_temporal_fatos_fase_inexistente))."],"comoResolver":["Informe como refer\xeancia uma fase que esteja no cronograma deste processo, ou inclua a fase no cronograma\\nantes de definir a refer\xeancia. Depois, envie a defini\xe7\xe3o da refer\xeancia temporal de novo."],"ondeAparece":["Defini\xe7\xe3o da refer\xeancia temporal dos fatos do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Referencia temporal fatos"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);